n=import_module('native-code').NativeCode();rows=n.disasm(0x591980,0x593bf0)
blocks=[('class options',0x592860,0x5928b0),('native mode labels',0x592a50,0x592a9a),('warrior initialization',0x593085,0x593299),('taoist initialization',0x5932b4,0x5934c8),('mage initialization',0x5934e3,0x59374a),('gender selection',0x5937a0,0x593a10)]
packs={name:json.loads(Path('public/assets/sprites/'+name+'/index.json').read_text(encoding='utf8')) for name in ['Data1','Data2']}
report={'passed':True,'source':str(n.source),'sourceSha256':hashlib.sha256(n.data).hexdigest(),'nativeCreateFunctionVA':'0x591980','verifiedStartingHPMP':{'战士':[25,5],'道士':[22,15],'法师':[17,15]},'assets':{'Data1':{'sha256':packs['Data1']['sha256'],'frames':{'titleBackground':8,'topBorder':3,'bottomBorder':4,'saveSelectionTitle':10,'creationTitle':11}},'Data2':{'sha256':packs['Data2']['sha256'],'frames':{'enter':1,'newGame':7,'continue':9,'deleteSave':11,'create':15,'back':17,'confirm':23}}},'adaptations':['Portrait 750x1624 crops the native mountain background and repositions native buttons; the loading label is excluded.','Game title is 小小传奇; the original embedded LP logo is replaced with rendered text.','Single-player creation/selection/targeted deletion/return-to-title flow; original LAN host/join and desktop process exit are not connected.','Only ordinary mode is offered; expert/hell gameplay rules remain outside this entry-screen implementation.','Normal native creation equips only starter cloth, with 1 skill point and 1 attribute point, an empty inventory and no learned skills. Cloth defense is already included in the cached original class total. Legacy web characters retain their progress and grants with a one-time numeric migration baseline.','Legacy v2 save is migrated into one character slot; active v2 header remains readable, while per-character flags, loot and pets are stored independently.'],'evidence':[{'meaning':name,'startVA':hex(lo),'endVA':hex(hi),'instructions':[f'{va:08x} {m} {o}' for va,m,o in rows if lo<=va<hi]} for name,lo,hi in blocks]}
Path('reports/native-entry-source.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf8');print(json.dumps({'passed':True,'verifiedStartingHPMP':report['verifiedStartingHPMP'],'nativeCreateFunctionVA':'0x591980'},ensure_ascii=False))
